#include <bits/stdc++.h>

using namespace std;

typedef pair<int,int> par;

const int MAXR = 11;
const int MAXN = 1000;
const int MAXM = 100100;
const int INF = (1<<29);

int ady[2*MAXM], flow[2*MAXM], capacity[2*MAXM], next_edge[2*MAXM];
int head[MAXN], current[MAXN], dist[MAXN], queue_arr[MAXN];
int edge_count, nodes_count, source, sink, enqueue_idx, dequeue_idx;

void initialize_maxflow( int node_count, int src, int dst ){
    nodes_count = node_count; source = src; sink = dst; edge_count = 2;
    for( int i = 0; i <= nodes_count; i++ ) head[i] = 0;
}
void insert_edge( int u, int v, int c ){
    ady[edge_count] = v; flow[edge_count] = 0; capacity[edge_count] = c; next_edge[edge_count] = head[u]; head[u] = edge_count++;
    ady[edge_count] = u; flow[edge_count] = 0; capacity[edge_count] = 0; next_edge[edge_count] = head[v]; head[v] = edge_count++;
}
bool bfs_leveling(){
    for( int u = 0; u <= nodes_count; u++ ) dist[u] = 0;
    enqueue_idx = dequeue_idx = 0;
    queue_arr[enqueue_idx++] = source;
    dist[source] = 1;
    while( dequeue_idx < enqueue_idx && !dist[sink] ){
        int u = queue_arr[dequeue_idx++];
        for( int e = head[u]; e; e = next_edge[e] ){
            int v = ady[e];
            if( !dist[v] && flow[e] < capacity[e] ){
                dist[v] = dist[u] + 1;
                queue_arr[enqueue_idx++] = v;
            }
        }
    }
    return dist[sink];
}
int dfs_flow( int u, int F ){
    if( u == sink ) return F;
    for( int e = current[u], f = 0; e; e = current[u] = next_edge[e] ){
        int v = ady[e];
        if( dist[u] < dist[v] && flow[e] < capacity[e] &&
            (f = dfs_flow( v , min( F , capacity[e] - flow[e] ) )) ){
            flow[e] += f;
            flow[e^1] -= f;
            return f;
        }
    }
    return 0;
}
int compute_max_flow(){
    int total_flow = 0, delta_flow = 0;
    while( bfs_leveling() ){
        for( int i = 0; i <= nodes_count; i++ ) current[i] = head[i];
        while( (delta_flow = dfs_flow( source , INF )) ) total_flow += delta_flow;
    }
    return total_flow;
}

int rows;
string grid1[MAXR];
string grid2[MAXR];

int dir_i[] = { 0 , 1 , 0 , -1 };
int dir_j[] = { 1 , 0 , -1 , 0 };

bool in_bounds( int i, int j ){
    return ( i >= 0 && j >= 0 && i < rows && j < rows && grid1[i][j] != 'Y' && grid1[i][j] != 'Z' );
}

int distance_arr[2][MAXR][MAXR];

void multi_source_bfs( int si, int sj, int phase ){
    for( int k = 0; k < rows; k++ ){
        for( int l = 0; l < rows; l++ ){
            distance_arr[phase][k][l] = 0;
        }
    }

    distance_arr[phase][si][sj] = 1;
    queue<par> q;
    q.push( par( si , sj ) );
    while( !q.empty() ){
        int ci = q.front().first;
        int cj = q.front().second;
        q.pop();

        if( phase == 1 && (distance_arr[0][ci][cj] && distance_arr[0][ci][cj] <= distance_arr[1][ci][cj]) ){
            continue;
        }

        for( int k = 0; k < 4; k++ ){
            int ni = ci + dir_i[k];
            int nj = cj + dir_j[k];

            if( in_bounds( ni , nj ) && !distance_arr[phase][ni][nj] ){
                distance_arr[phase][ni][nj] = distance_arr[phase][ci][cj] + 1;
                q.push( par( ni , nj ) );
            }
        }
    }
}

int node_index[2][MAXR][MAXR];

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    int T; cin >> rows >> T;

    int zi = 0, zj = 0;

    int node_count = 0, src = 0, dst = 0;

    for( int i = 0; i < rows; i++ ){
        cin >> grid1[i];
        for( int j = 0; j < rows; j++ ){
            if( grid1[i][j] == 'Z' ){
                zi = i;
                zj = j;
            }
            else if( grid1[i][j] != 'Y' ){
                node_count++;
                node_index[0][i][j] = node_count;
            }
        }
    }

    for( int i = 0; i < rows; i++ ){
        cin >> grid2[i];
        for( int j = 0; j < rows; j++ ){
            if( grid2[i][j] != 'Y' && grid2[i][j] != 'Z' ){
                node_count++;
                node_index[1][i][j] = node_count;
            }
        }
    }

    node_count++;
    src = 0;
    dst = node_count;

    initialize_maxflow( node_count , src , dst );

    for( int i = 0; i < rows; i++ ){
        for( int j = 0; j < rows; j++ ){
            if( grid1[i][j] != 'Z' && grid1[i][j] != 'Y' ){
                insert_edge( src , node_index[0][i][j] , grid1[i][j] - '0' );
                insert_edge( node_index[1][i][j] , dst , grid2[i][j] - '0' );
            }
        }
    }

    multi_source_bfs( zi , zj, 0 );

    for( int i = 0; i < rows; i++ ){
        for( int j = 0; j < rows; j++ ){
            if( grid1[i][j] > '0' && grid1[i][j] <= '9' ){
                multi_source_bfs( i , j , 1 );
                for( int ii = 0; ii < rows; ii++ ){
                    for( int jj = 0; jj < rows; jj++ ){
                        if( grid2[ii][jj] > '0' && grid2[ii][jj] <= '9' ){
                            if( distance_arr[1][ii][jj] && (!distance_arr[0][ii][jj] || distance_arr[0][ii][jj] >= distance_arr[1][ii][jj]) &&
                                distance_arr[1][ii][jj]-1 <= T ){
                                insert_edge( node_index[0][i][j] , node_index[1][ii][jj] , INF );
                            }
                        }
                    }
                }
            }
        }
    }

    cout << compute_max_flow() << '\n';
}
